When `schema.field` is not set, errors are emitted with `field: 'unknown'`. In `validateFields()`, you already know the field key but don’t propagate it into the schema/context. Consider setting `schema.field` (or passing the field name separately) so emitted errors reliably reference the correct field.
```suggestion
      const schemaWithField: AdvancedValidationSchema = {
        ...schema,
        field: schema.field ?? field,
      };
      results[field] = await this.validate(value, schemaWithField, context);
```

`buildCondition` currently hard-codes the operator to '=' and always uses `condition.value`, ignoring `condition.operator` and `condition.values`. This will produce incorrect AST for anything other than simple equality (e.g., `in`, `between`, `is_null`, etc.). Update this to map `AdvancedFilterOperator` to the appropriate `ComparisonOperator` and build operands from `value` vs `values` based on the operator.
```suggestion
  /**
   * Map an AdvancedFilter operator to a low-level ComparisonOperator.
   * Defaults to '=' for unknown or missing operators to preserve existing behavior.
   */
  private mapComparisonOperator(
    operator: AdvancedFilterCondition['operator'] | undefined,
  ): OperatorNode['operator'] {
    switch (operator) {
      case 'eq':
      case undefined:
        return '=' as OperatorNode['operator'];
      case 'neq':
        return '!=' as OperatorNode['operator'];
      case 'gt':
        return '>' as OperatorNode['operator'];
      case 'gte':
        return '>=' as OperatorNode['operator'];
      case 'lt':
        return '<' as OperatorNode['operator'];
      case 'lte':
        return '<=' as OperatorNode['operator'];
      case 'in':
        return 'in' as OperatorNode['operator'];
      case 'not_in':
        return 'not_in' as OperatorNode['operator'];
      case 'between':
        return 'between' as OperatorNode['operator'];
      case 'is_null':
        return 'is_null' as OperatorNode['operator'];
      case 'is_not_null':
        return 'is_not_null' as OperatorNode['operator'];
      case 'like':
        return 'like' as OperatorNode['operator'];
      case 'not_like':
        return 'not_like' as OperatorNode['operator'];
      default:
        // Fallback: pass through as-is, but ensure type compatibility.
        return (operator as unknown) as OperatorNode['operator'];
    }
  }

  private buildCondition(condition: AdvancedFilterCondition): OperatorNode {
    const fieldOperand = this.buildField(condition.field);
    const operator = this.mapComparisonOperator(condition.operator);

    const valuesArray =
      Array.isArray((condition as any).values) && (condition as any).values.length > 0
        ? (condition as any).values
        : condition.value !== undefined
        ? [condition.value]
        : [];

    let valueOperands: LiteralNode[] = [];

    switch (operator) {
      case 'in':
      case 'not_in': {
        valueOperands = valuesArray.map(v => this.buildLiteral(v));
        break;
      }
      case 'between': {
        if (valuesArray.length >= 2) {
          valueOperands = [
            this.buildLiteral(valuesArray[0]),
            this.buildLiteral(valuesArray[1]),
          ];
        } else if (valuesArray.length === 1) {
          valueOperands = [this.buildLiteral(valuesArray[0])];
        }
        break;
      }
      case 'is_null':
      case 'is_not_null': {
        // Unary operators: no value operands, just the field.
        valueOperands = [];
        break;
      }
      default: {
        if (valuesArray.length > 0) {
          valueOperands = [this.buildLiteral(valuesArray[0])];
        }
        break;
      }
    }

    return {
      type: 'operator',
      operator,
      operands: [fieldOperand, ...valueOperands],
